    public Map<String,Object> bookViewing(@PathVariable UUID id,@RequestBody Map<String,Object> body){if(body.keySet().stream().anyMatch(k->!Set.of("version","bookingNotes").contains(k)))throw bad("Unsupported booking field");var record=viewing(id,true);UUID flat=(UUID)record[0];requirePermission("VIEWING_BOOK",flat);if(!"AVAILABLE".equals(record[1]))throw new ResponseStatusException(HttpStatus.CONFLICT,"Viewing slot is no longer available");var actor=access.identity();if(actor.memberId()==null)throw new AccessDeniedException("A member account is required to book a viewing");long version=expectedVersion(body.get("version"));if(version!=((Number)record[4]).longValue())throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Supply the current viewing version");Map<String,Object> details=new LinkedHashMap<>(readDetails((String)record[3]));LocalDateTimeValue slot=slot(details.get("slot"));if(!slot.instant().isAfter(java.time.Instant.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"This viewing time has passed");String notes=Objects.toString(body.getOrDefault("bookingNotes",""),"").trim();if(notes.length()>500)throw bad("Booking notes must be at most 500 characters");String now=java.time.Instant.now().toString();details.put("bookedAt",now);details.put("bookedBy",actor.memberId());details.put("bookingNotes",notes);details.remove("cancelledAt");details.remove("cancellationReason");appendViewingHistory(details,Map.of("action","BOOKED","memberId",actor.memberId(),"at",now));try{if(db.update("UPDATE rental_operations SET status='BOOKED',member_id=?,details=?::jsonb,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=? AND status='AVAILABLE' AND version=?",actor.memberId(),json.writeValueAsString(details),id,version)==0)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Viewing version is stale");}catch(org.springframework.dao.DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"You already have a booking at this time",e);}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Booking update failed",e);}Map<String,Object> result=Map.of("id",id,"flatId",flat,"status","BOOKED","memberId",actor.memberId(),"details",safeViewingDetails(details),"version",version+1);audit.record("BOOK_VIEWING","RENTAL_OPERATION",id,Map.of("status","AVAILABLE"),result);return result;}

